import {load,realtime,departures,distance,BASE,planJourney} from './transit.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let db,rt,pos,accuracy,view='near',query='',selected=null,map,markers,manual=false,loading=true;let saved=new Set(JSON.parse(localStorage.getItem('tuka-saved')||'[]'));let timer,tripSelected=null,destination=null,pinMode=null,originOverride=null,lastJourney=null;const clock=t=>new Intl.DateTimeFormat('mk',{timeZone:'Europe/Skopje',hour:'2-digit',minute:'2-digit'}).format(t);const norm=s=>String(s).toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/a/g,'а');
if(localStorage.getItem('tuka-dark')==='1')document.body.classList.add('dark');$('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('tuka-dark',document.body.classList.contains('dark')?'1':'0')};
function locate(){if(!navigator.geolocation){$('#location').textContent='Локацијата не е поддржана. Избери постојка.';return}$('#location').textContent='Се бара локацијата…';navigator.geolocation.getCurrentPosition(p=>{pos={lat:p.coords.latitude,lon:p.coords.longitude};accuracy=p.coords.accuracy;manual=false;$('#location').textContent=accuracy>80?`Локација ±${Math.round(accuracy)} м · провери ја постојката`:'Твојата локација · постојки во близина';render();if(map)map.setView([pos.lat,pos.lon],16)},()=>{$('#location').textContent='Дозволи локација или избери постојка на мапата.';render()},{enableHighAccuracy:true,timeout:15000,maximumAge:30000})}
$('#locate').onclick=locate;locate();
$('#search').oninput=e=>{query=e.target.value;selected=null;render()};$('#clear').onclick=()=>{$('#search').value='';query='';selected=null;tripSelected=null;render()};
for(let b of document.querySelectorAll('nav button'))b.onclick=()=>{view=b.dataset.view;selected=null;tripSelected=null;for(let x of document.querySelectorAll('nav button'))x.classList.toggle('active',x===b);render()};
$('#refresh').onclick=async()=>{await refresh();render()};
function setStatus(){if(!db)return;let freshness=rt?(Date.now()/1000-rt.timestamp):Infinity;$('#status').textContent=freshness>=0&&freshness<120?`Во живо · ажурирано ${clock(rt.timestamp*1000)} · автоматско освежување на 30 сек.`:'Распоред на ЈСП · во моментов нема свежи податоци во живо.';$('#feeddate').textContent=`Распоред преземен ${clock(Date.now())} · верзија ${db.info.feed_version}`}
async function refresh(){try{rt=await realtime()}catch{rt=null}setStatus()}
function stopRoutes(s){return [...new Set((db.byStop.get(s.id)||[]).map(t=>db.trips.get(t.trip_id)?.route_id))].map(id=>db.routes.get(id)).filter(Boolean).sort((a,b)=>a.route_short_name.localeCompare(b.route_short_name,'mk',{numeric:true}))}
function arrivals(s,limit=4){let d=departures(db,rt,s.id,Date.now(),limit);if(!d.length)return '<p class="muted">Нема поаѓања во следните 4 часа.</p>';return d.map(a=>`<div class="arrival"><button class="route" data-trip="${esc(a.trip.trip_id)}">${esc(a.route.route_short_name)}</button><span class="dest">${esc(a.trip.trip_headsign||a.route.route_long_name)}</span><span class="time ${a.live?'live':''}">${Math.max(0,Math.ceil((a.time-Date.now())/60000))}<span style="font-size:13px"> мин</span><small>${a.live?'Во живо':'Распоред'} · ${clock(a.time)}</small></span></div>`).join('')}
function card(s){let meters=pos?distance(pos,s):null;return `<article class="stop"><div class="stophead"><div><button class="stopname" data-stop="${s.id}">${esc(s.name)}</button><div class="meta">${meters!=null?`${Math.round(meters)} м · ~${Math.max(1,Math.ceil(meters/75))} мин пеш · `:''}Постојка ${esc(s.stop_code||s.id)}</div></div><button class="star ${saved.has(s.id)?'on':''}" data-save="${s.id}" aria-label="${saved.has(s.id)?'Отстрани од':'Додај во'} зачувани">${saved.has(s.id)?'★':'☆'}</button></div>${arrivals(s)}<button class="more" data-stop="${s.id}">Сите линии и пристигнувања</button></article>`}
function getStops(){let list=db.stops.filter(s=>db.byStop.has(s.id));if(view==='saved')list=list.filter(s=>saved.has(s.id));if(query){let q=norm(query);list=list.filter(s=>norm(s.name).includes(q)||s.stop_code===query||stopRoutes(s).some(r=>norm(r.route_short_name)===q)||departures(db,null,s.id,Date.now(),4).some(a=>norm(a.trip.trip_headsign).includes(q)))}if(pos)list.sort((a,b)=>distance(pos,a)-distance(pos,b));return list}
function render(){if(!db)return;if(tripSelected){showTrip(tripSelected);return;}$('#planner').hidden=view!=='plan';$('#mapwrap').hidden=view!=='map';$('#board').hidden=view==='plan'||!!selected;$('#detail').hidden=!selected;if(selected)return showStop(selected);if(view==='plan')return;if(view==='map')showMap();$('#boardtitle').textContent=query?'Резултати':view==='saved'?'Твои постојки':pos?'Блиски постојки':'Избери постојка';if(!pos&&!query&&view==='near'){$('#results').innerHTML='<div class="empty">Дозволи пристап до локацијата за веднаш да ги видиш автобусите на твојата постојка. Можеш и да избереш постојка на мапата или да пребараш.</div>';return}let list=getStops();if(pos&&!query&&view!=='saved'){list=list.filter(s=>distance(pos,s)<1200).slice(0,6)}else list=list.slice(0,20);$('#results').innerHTML=list.length?list.map(card).join(''):'<div class="empty">Нема постојки во овој избор. Пребарај или избери на мапата.</div>'}
function showStop(id){let s=db.stops.find(s=>s.id===id);$('#detail').innerHTML=`<button class="back" data-back>Назад до постојките</button><article class="stop"><div class="stophead"><h2>${esc(s.name)}</h2><button class="star ${saved.has(s.id)?'on':''}" data-save="${id}" aria-label="Зачувај постојка">${saved.has(id)?'★':'☆'}</button></div><div class="meta">Постојка ${esc(s.stop_code||id)} ${pos?'· '+Math.round(distance(pos,s))+' м од тебе':''}</div><div class="chips">${stopRoutes(s).map(r=>`<span class="chip">${esc(r.route_short_name)}</span>`).join('')}</div>${arrivals(s,30)}<a class="more" href="https://www.google.com/maps/dir/?api=1&destination=${s.lat},${s.lon}&travelmode=walking" target="_blank" rel="noopener">Насоки пеш до постојката</a></article>`}
function showTrip(id){tripSelected=id;let t=db.trips.get(id),r=db.routes.get(t.route_id);$('#board').hidden=true;$('#mapwrap').hidden=true;$('#detail').hidden=false;$('#detail').innerHTML=`<button class="back" data-back>Назад до постојките</button><article class="stop"><h2><span class="chip">${esc(r.route_short_name)}</span> ${esc(t.trip_headsign)}</h2><p class="muted">Постојки по редослед за ова патување</p><ol class="timeline">${db.times.get(id).map(x=>{let s=db.stops.find(s=>s.id===x.stop_id);return `<li><button class="stopname" data-stop="${x.stop_id}">${esc(s?.name||x.stop_id)}</button></li>`}).join('')}</ol></article>`}
$('#results').onclick=$('#detail').onclick=e=>{let b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-save')){let id=b.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);localStorage.setItem('tuka-saved',JSON.stringify([...saved]));render()}else if(b.dataset.stop){tripSelected=null;selected=b.dataset.stop;render()}else if(b.dataset.trip){showTrip(b.dataset.trip)}else if(b.hasAttribute('data-back')){selected=null;tripSelected=null;render()}};
function showMap(){if(!window.L){$('#map').innerHTML='Мапата не може да се вчита. Постојките се достапни во списокот.';return}if(!map){map=L.map('map').setView(pos?[pos.lat,pos.lon]:[41.997,21.431],15);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);markers=L.layerGroup().addTo(map);map.on('click',e=>{let point={lat:e.latlng.lat,lon:e.latlng.lng,name:'Избрано место на мапата'};if(pinMode){if(pinMode==='destination'){destination=point;$('#destlabel').textContent='Дестинација: поставен пин'}else{originOverride=point;$('#originlabel').textContent='Почеток: поставен пин'}pinMode=null;view='plan';document.querySelector('[data-view=plan]').click()}else{pos=point;manual=true;$('#location').textContent='Избрано место на мапата';render()}})}map.invalidateSize();markers.clearLayers();let center=pos||{lat:map.getCenter().lat,lon:map.getCenter().lng};if(pos)L.circle([pos.lat,pos.lon],{radius:manual?15:Math.min(accuracy||15,200),color:'#006b60'}).addTo(markers);db.stops.filter(s=>distance(center,s)<3000&&db.byStop.has(s.id)).forEach(s=>L.circleMarker([s.lat,s.lon],{radius:6,color:'#006b60',fillColor:'#b9f34f',fillOpacity:1,weight:2}).addTo(markers).bindTooltip(s.name).on('click',()=>{selected=s.id;render()}))}
function choosePin(mode){pinMode=mode;view='map';document.querySelector('[data-view=map]').click();$('#pinhint').textContent=mode==='destination'?'Допрете каде сакате да стигнете.':'Допрете од каде тргнувате.'}
$('#destpin').onclick=()=>choosePin('destination');$('#originpin').onclick=()=>choosePin('origin');$('#to').onchange=()=>{destination=db.stops.find(s=>s.id===$('#to').value);$('#destlabel').textContent=destination.name;$('#destination').value=destination.name};
let placeChoices=[];$('#findplace').onclick=async()=>{let q=$('#destination').value.trim();if(q.length<2)return;$('#places').innerHTML='<p class="muted">Се пребарува…</p>';placeChoices=db.stops.filter(s=>norm(s.name).includes(norm(q))).slice(0,6);try{let r=await fetch('https://photon.komoot.io/api/?q='+encodeURIComponent(q)+'&lat=41.997&lon=21.431&limit=8');if(!r.ok)throw Error();let data=await r.json();let places=data.features.map(f=>({lat:f.geometry.coordinates[1],lon:f.geometry.coordinates[0],name:[f.properties.name,f.properties.street,f.properties.housenumber,f.properties.city].filter(Boolean).join(', ')})).filter(p=>distance(p,{lat:41.997,lon:21.431})<45000);placeChoices.push(...places)}catch{}$('#places').innerHTML=placeChoices.length?placeChoices.map((p,i)=>`<button class="place" data-place="${i}">${esc(p.name)}</button>`).join(''):'<p class="muted">Нема резултати. Постави пин на мапата.</p>'};$('#destination').onkeydown=e=>{if(e.key==='Enter')$('#findplace').click()};$('#places').onclick=e=>{let b=e.target.closest('[data-place]');if(!b)return;destination=placeChoices[+b.dataset.place];$('#destlabel').textContent=destination.name;$('#destination').value=destination.name;$('#places').innerHTML=''};
$('#plan').onclick=async()=>{let origin=originOverride||pos;if(!origin){$('#journeys').innerHTML='<p class="muted">Дозволи локација или избери почеток на мапата.</p>';return}if(!destination){$('#journeys').innerHTML='<p class="muted">Пребарај дестинација или постави пин.</p>';return}$('#journeys').innerHTML='<p class="muted">Се споредуваат патувањата…</p>';await new Promise(r=>setTimeout(r,30));let now=Date.now(),best=planJourney(db,rt,origin,destination,now);lastJourney={origin,destination};$('#journeys').innerHTML=best.length?`<p class="muted">Пресметано ${clock(now)} · подредено по најрано пристигнување</p>`+best.map((r,i)=>{let buses=r.legs.filter(l=>l.type==='bus');return `<article class="journey"><div class="sectionhead"><strong>${i===0?'НАЈБРЗО':'АЛТЕРНАТИВА'}</strong><strong>${Math.ceil((r.arrival-now)/60000)} мин</strong></div><h2>Пристигнување ${clock(r.arrival)}</h2><ol class="timeline">${r.legs.map(l=>l.type==='bus'?`<li><strong><span class="chip">${esc(l.route.route_short_name)}</span> ${esc(l.headsign)}</strong><br>${esc(l.from?.name)} · ${clock(l.start)}<br>Слези: ${esc(l.to?.name)} · ~${clock(l.end)}<br><span class="muted">${l.stops} постојки · ${l.live?'поаѓање во живо':'поаѓање според распоред'} · ${l.arrivalLive?'пристигнување во живо':'пристигнување е проценка'}</span></li>`:l.type==='transfer'?`<li>Преседни ${l.from?.id!==l.to?.id?'на '+esc(l.to?.name):'на истата постојка'}<br><span class="muted">~${Math.round(l.meters*1.3)} м пеш + 2 мин резерва</span></li>`:`<li>Пеш ~${Math.round(l.meters*1.3)} м · ${Math.round((l.end-l.start)/60000)} мин${l.to?.stop_id?' до '+esc(l.to.name):' до дестинацијата'}</li>`).join('')}</ol><p class="muted">${buses.length?buses.length-1+' преседнувања':'Само пеш'} · времињата може да се променат</p></article>`}).join(''):'<div class="empty">Нема патување во следните 4 часа со до две преседнувања и до 800 м до почетна/крајна постојка. Обиди се со друга блиска точка.</div>'};

try{db=await load();let options=db.stops.filter(s=>db.byStop.has(s.id)).sort((a,b)=>a.name.localeCompare(b.name,'mk')).map(s=>`<option value="${s.id}">${esc(s.name)} (${esc(s.stop_code||s.id)})</option>`).join('');$('#to').innerHTML='<option value="">Избери постојка</option>'+options;await refresh();render();timer=setInterval(()=>{if(!document.hidden)refresh().then(render)},30000)}catch(e){$('#status').textContent='Не успеавме да ги вчитаме податоците од ЈСП. Провери интернет и обиди се повторно.';$('#results').innerHTML='<div class="empty"><button onclick="location.reload()">Обиди се повторно</button></div>';console.error(e)}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&db)refresh().then(render)});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
